using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using UnityEngine;
using UnityEngine.InputSystem;
using UnityEngine.InputSystem.LowLevel;
using UnityEngine.SceneManagement;
public sealed class CompletionBuildVerification:MonoBehaviour
{
 static string phase,output;readonly List<string> lines=new(),errors=new();Gamepad pad;Keyboard kb;
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]static void Initialize(){if(Application.isEditor)return;var args=Environment.GetCommandLineArgs();int i=Array.IndexOf(args,"-completion-verify");if(i<0||i+2>=args.Length)return;phase=args[i+1];output=Path.GetFullPath(args[i+2]);if(File.Exists(output)){Application.Quit(2);return;}var go=new GameObject("Completion prescribed verification");DontDestroyOnLoad(go);go.AddComponent<CompletionBuildVerification>();}
 PlayerInputReader Player=>RoomSession.Instance.Player;
 void Log(string m,string s,LogType t){if(t is LogType.Error or LogType.Exception or LogType.Assert)errors.Add(m+s);}
 void Check(bool ok,string m){if(!ok)throw new Exception(m);lines.Add("PASS: "+m);}
 IEnumerator Start(){Application.logMessageReceived+=Log;InputSystem.settings.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;QualitySettings.vSyncCount=0;Application.targetFrameRate=60;pad=InputSystem.AddDevice<Gamepad>();kb=InputSystem.AddDevice<Keyboard>();var stack=new Stack<IEnumerator>();stack.Push(Tests());bool fail=false;while(stack.Count>0&&!fail){object next=null;try{if(!stack.Peek().MoveNext()){stack.Pop();continue;}next=stack.Peek().Current;}catch(Exception e){fail=true;lines.Add("FAIL: "+e);}if(next is IEnumerator child)stack.Push(child);else if(!fail)yield return next;}Application.logMessageReceived-=Log;fail|=errors.Count>0;lines.AddRange(errors);lines.Add("Error/Exception/Assert "+errors.Count);lines.Insert(0,(fail?"FAIL ":"PASS ")+"Windows exe "+phase+" Unity="+Application.unityVersion+" PID="+System.Diagnostics.Process.GetCurrentProcess().Id);Directory.CreateDirectory(Path.GetDirectoryName(output));File.WriteAllLines(output,lines);Application.Quit(fail?1:0);}
 IEnumerator Until(Func<bool> test,float seconds=6){double end=Time.realtimeSinceStartupAsDouble+seconds;while(!test()){if(Time.realtimeSinceStartupAsDouble>end)throw new Exception("Completion timeout");yield return null;}}
 IEnumerator Pad(GamepadButton? button=null){InputSystem.QueueStateEvent(pad,button.HasValue?new GamepadState().WithButton(button.Value):new GamepadState());yield return null;yield return new WaitForSecondsRealtime(.03f);}
 IEnumerator Tap(GamepadButton button){yield return Pad(button);yield return Pad();}
 IEnumerator Keys(params Key[] keys){InputSystem.QueueStateEvent(kb,new KeyboardState(keys));yield return null;yield return new WaitForSecondsRealtime(.03f);}
 void Place(Vector2 pos){Player.ClearTransientInput();Player.transform.position=pos;var body=Player.GetComponent<Rigidbody2D>();body.position=pos;body.linearVelocity=Vector2.zero;Physics2D.SyncTransforms();}
 IEnumerator Ready(){yield return Until(()=>RoomSession.Instance?.Player!=null&&!RoomSession.Instance.Transitioning&&!RoomSession.Instance.Respawning);yield return new WaitForSecondsRealtime(.15f);}
 IEnumerator NewGame(){var menu=FindFirstObjectByType<SaveMenu>();if(menu.CanContinue)yield return Tap(GamepadButton.DpadDown);yield return Tap(GamepadButton.South);if(FindFirstObjectByType<SaveMenu>()?.Confirming==true)yield return Tap(GamepadButton.South);yield return Ready();Check(RoomSession.Instance.CurrentRoomId=="A01","pad new game enters A01");}
 IEnumerator PauseTitle(){yield return Tap(GamepadButton.Start);Check(Player.Paused,"pad Start Pause");yield return Tap(GamepadButton.DpadDown);Check(Player.PauseSelection==1,"pad selects Pause title");yield return Tap(GamepadButton.South);yield return Until(()=>FindFirstObjectByType<SaveMenu>()!=null);yield return new WaitForSecondsRealtime(.1f);Check(RoomSession.Instance==null&&Time.timeScale==1,"pad Pause title / session cleanup / scale1");}
 IEnumerator Tests(){yield return new WaitForSecondsRealtime(.3f);var menu=FindFirstObjectByType<SaveMenu>();Check(menu!=null&&SceneManager.GetActiveScene().name=="Menu","starts Menu");
  if(phase=="continue"){
   Check(ProgressSave.TryLoad(out var before)&&before.bossDefeated&&!before.endingReached,"fresh process finds kill saved before ending");yield return Tap(GamepadButton.South);yield return Until(()=>FindFirstObjectByType<EndingMenu>()!=null);Check(ProgressSave.TryLoad(out var data)&&data.bossDefeated&&data.endingReached,"Continue routes Ending and saves reached");yield return Tap(GamepadButton.South);yield return Until(()=>FindFirstObjectByType<SaveMenu>()!=null);yield return new WaitForSecondsRealtime(.1f);Check(FindFirstObjectByType<SaveMenu>().CanContinue,"pad Ending title return");
   yield return Keys(UnityEngine.InputSystem.Key.Enter);yield return Keys();yield return Until(()=>FindFirstObjectByType<EndingMenu>()!=null);yield return Keys(UnityEngine.InputSystem.Key.Z);yield return Keys();yield return Until(()=>FindFirstObjectByType<SaveMenu>()!=null);Check(true,"Enter Continue / Z Ending title");yield return NewGame();Check(ProgressSave.TryLoad(out var reset)&&!reset.dash&&!reset.doubleJump&&!reset.bossDefeated&&!reset.endingReached&&reset.checkpointId=="CP-A01","confirmed new game resets all progress");yield return PauseTitle();yield return Tap(GamepadButton.DpadDown);yield return Tap(GamepadButton.DpadDown);Check(FindFirstObjectByType<SaveMenu>().Selection==2,"Quit reachable by pad");yield break;
  }
  if(phase=="final"){
   Check(menu.CanContinue,"final route slot can Continue CP-C04");yield return Tap(GamepadButton.South);yield return Ready();Check(RoomSession.Instance.CurrentRoomId=="C04"&&Player.GetComponent<PlayerMotor>().hasDoubleJump&&Player.GetComponent<PlayerDash>().hasDash,"final Continue both abilities CP-C04");
  }else{yield return NewGame();yield return PauseTitle();yield return Tap(GamepadButton.South);yield return Ready();Check(RoomSession.Instance.RequestTransition("C04","Assets/Scenes/C04.unity","FromLeft"),"direct C04 verification setup");yield return Until(()=>RoomSession.Instance.CurrentRoomId=="C04"&&!RoomSession.Instance.Transitioning);yield return Ready();Place(FindFirstObjectByType<Checkpoint>().transform.position);yield return new WaitForSeconds(.15f);RoomSession.Instance.GrantDash();RoomSession.Instance.GrantDoubleJump();}
  var exit=Array.Find(FindObjectsByType<RoomExit>(FindObjectsSortMode.None),e=>e.destinationRoomId=="C06");Check(exit!=null&&exit.enabled,"C04 C06 door enabled");Place(exit.transform.position);yield return new WaitForFixedUpdate();yield return null;yield return Until(()=>RoomSession.Instance.CurrentRoomId=="C06"&&!RoomSession.Instance.Transitioning);yield return Ready();var boss=FindFirstObjectByType<BossEncounter>();Place(new Vector2(8,1.81f));yield return Until(()=>boss.Fighting);
  double killed;
  if(phase=="final"){
   while(boss.HP>0){yield return Until(()=>boss.State==BossEncounter.Phase.MeleeRecovery||boss.State==BossEncounter.Phase.WaveRecovery);if(boss.State==BossEncounter.Phase.WaveRecovery)yield return new WaitForSeconds(.3f);yield return Keys(UnityEngine.InputSystem.Key.RightArrow);yield return new WaitForFixedUpdate();yield return Keys();Place(new Vector2(15.75f,1.81f));double finish=boss.PhaseStarted+boss.tuning.recovery;while(Time.timeAsDouble+.19<finish&&boss.HP>0){yield return Keys(UnityEngine.InputSystem.Key.X);yield return Keys();yield return new WaitForSecondsRealtime(.36f);}if(boss.HP>0){Place(new Vector2(8,1.81f));yield return Until(()=>boss.State!=BossEncounter.Phase.MeleeRecovery&&boss.State!=BossEncounter.Phase.WaveRecovery);}}
   Check(boss.Hits==20,"exe actual X twenty hits defeats boss");killed=Time.realtimeSinceStartupAsDouble;
  }else{killed=Time.realtimeSinceStartupAsDouble;boss.ReceiveHit(20,Player.transform.position);}
  Check(ProgressSave.TryLoad(out var immediate)&&immediate.bossDefeated&&!immediate.endingReached,"boss flag persisted synchronously before light");Check(Player.InputLocked&&!Player.GetComponent<PlayerHealth>().TakeDamage(1,Vector2.zero),"victory stops attacks and damage");
  if(phase=="kill-now"){lines.Add($"MEASURE process exits {Time.realtimeSinceStartupAsDouble-killed:F4}s after kill, before 2s Ending. Separate Continue process required.");yield break;}
  yield return Until(()=>FindFirstObjectByType<EndingMenu>()!=null);double elapsed=Time.realtimeSinceStartupAsDouble-killed;lines.Add($"MEASURE kill -> Ending real={elapsed:F4}s");Check(elapsed>=1.8&&elapsed<3,"approximately2s light then Ending");Check(ProgressSave.TryLoad(out var complete)&&complete.bossDefeated&&complete.endingReached,"endingReached saved");yield return Tap(GamepadButton.South);yield return Until(()=>FindFirstObjectByType<SaveMenu>()!=null);Check(Time.timeScale==1,"pad Ending returns Menu scale1");lines.Add("Prescribed virtual gamepad / keyboard. Physical pad and natural play time not tested.");
 }
}
